const ai = $('Ollama').first().json.response;
let d;
try {
  let raw = String(ai || '');
  raw = raw.replace(/```(?:json)?\s*/gi, '').replace(/```\s*/g, '');
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Sin JSON en respuesta');
  d = JSON.parse(m[0]);
} catch(e) {
  throw new Error('JSON inválido de Ollama: ' + e.message + ' | Respuesta: ' + String(ai).substring(0, 200));
}
const gv = (v) => {
  if (v === null || v === undefined) return 'No disponible';
  const s = String(v).trim();
  if (!s || ['null','none','n/a','-','undefined'].includes(s.toLowerCase())) return 'No disponible';
  return s;
};
let rN = gv(d.factura_numero), rF = gv(d.factura_fecha);
const fD = (s) => {
  if (s === 'No disponible') return s;
  const clean = s.replace(/[^0-9\-\/\.]/g, '');
  const p = clean.split(/[\-\/\.]/); if (p.length < 3) return s;
  let y, mo, dd;
  if (p[0].length === 4) { y=p[0]; mo=p[1]; dd=p[2]; } else { dd=p[0]; mo=p[1]; y=p[2]; }
  if (y.length === 2) y = '20' + y;
  return dd.padStart(2,'0') + '/' + mo.padStart(2,'0') + '/' + y;
};
let eN=gv(d.empresa_nombre), eC=gv(d.empresa_cif), eD=gv(d.empresa_direccion), eT=gv(d.empresa_telefono);
let cN=gv(d.cliente_nombre), cC=gv(d.cliente_cif), cDir=gv(d.cliente_direccion);
const isClient = (n) => /innovatek|alejandro|calvo|yuniq/i.test(String(n || ''));
if (isClient(eN) && !isClient(cN)) { let t; t=eN; eN=cN; cN=t; t=eC; eC=cC; cC=t; t=eD; eD=cDir; cDir=t; }
if (isClient(cN)) { cN='INNOVATEK IT CONSULTING C.B.'; cC='E20882726'; cDir='INNOVATEK -ZALDIZURRETA 19 AZPIA, 20200 BEASAIN (Gipuzkoa), España'; }
if (/ontinet/i.test(eN)) eN='ONTINET.COM S.L.U.';
const toNum = (v) => parseFloat(String(v || '0').replace(',','.')) || 0;
let base=toNum(d.base_imponible_total), iva=toNum(d.iva_total), total=toNum(d.total_factura);
if (total === 0 && (base > 0 || iva > 0)) total = base + iva;
else if (base > 0 && Math.abs((base+iva)-total) > 0.05) total = base + iva;
const esc = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const q = String.fromCharCode(34);
const c = (t,v) => '<ss:Cell><ss:Data ss:Type='+q+t+q+'>'+v+'</ss:Data></ss:Cell>';
let row = '<ss:Row>';
row += c('String',esc(rN)) + c('String',esc(fD(rF))) + c('String',esc(eN)) + c('String',esc(eC)) + c('String',esc(eD)) + c('String',esc(eT)) + c('String',esc(cN)) + c('String',esc(cC)) + c('String',esc(cDir)) + c('Number',String(base)) + c('Number',String(iva)) + c('Number',String(total)) + c('String',esc(gv(d.cuenta_bancaria_iban))) + c('String',esc(gv(d.metodo_pago)));
row += '</ss:Row>';
let rutaArchivo = 'webhook';
try { const p = $item(0).$node['Separar Archivos'].json.path; if(p) rutaArchivo=p; } catch(e){}
try { const p = $item(0).$node['Extraer Adjuntos Email'].json.savePath; if(p && rutaArchivo==='webhook') rutaArchivo=p; } catch(e){}
let xml = '';
try { const b = await this.helpers.getBinaryDataBuffer(0,'data'); if(b && b.length>0) xml = b.toString('utf-8'); } catch(e){}
if (rN !== 'No disponible' && xml && xml.includes('>'+esc(rN)+'</ss:Data>')) {
  return [{ json: { success: false, reason: 'Duplicate', invoiceNum: rN, file: rutaArchivo } }];
}
const re = /(<\/(?:ss:)?Table\s*>)/i;
if (xml && re.test(xml)) {
  xml = xml.replace(re, row + '\n$1');
} else {
  const hc = (t) => '<ss:Cell ss:StyleID='+q+'header'+q+'><ss:Data ss:Type='+q+'String'+q+'>'+t+'</ss:Data></ss:Cell>';
  const hdr = '<ss:Row ss:Height='+q+'30'+q+'>'+hc('N Factura')+hc('Fecha')+hc('Empresa')+hc('CIF/NIF Empresa')+hc('Dir Empresa')+hc('Tel Empresa')+hc('Cliente')+hc('CIF/NIF Cliente')+hc('Dir Cliente')+hc('Base Imponible')+hc('IVA')+hc('Total')+hc('IBAN')+hc('Método Pago')+'</ss:Row>';
  xml = '<?xml version='+q+'1.0'+q+' encoding='+q+'UTF-8'+q+'?><?mso-application progid='+q+'Excel.Sheet'+q+'?><Workbook xmlns='+q+'urn:schemas-microsoft-com:office:spreadsheet'+q+' xmlns:ss='+q+'urn:schemas-microsoft-com:office:spreadsheet'+q+'><Styles><Style ss:ID='+q+'Default'+q+'><Font ss:FontName='+q+'Calibri'+q+' ss:Size='+q+'11'+q+'/></Style><Style ss:ID='+q+'header'+q+'><Font ss:Bold='+q+'1'+q+' ss:Color='+q+'#FFFFFF'+q+' ss:FontName='+q+'Calibri'+q+' ss:Size='+q+'11'+q+'/><Interior ss:Color='+q+'#1F4E79'+q+' ss:Pattern='+q+'Solid'+q+'/></Style></Styles><Worksheet ss:Name='+q+'Facturas'+q+'><Table>'+hdr+row+'</Table></Worksheet></Workbook>';
}
return [{ json: { success: true, file: rutaArchivo }, binary: { data: { data: Buffer.from(xml,'utf-8').toString('base64'), mimeType:'application/vnd.ms-excel', fileName:'tabla_excell_facturas.xls', fileExtension:'xls' } } }];

// Extrae adjuntos válidos (pdf, jpg, jpeg, png) del email y devuelve un ítem por cada uno
const validExt = /\.(pdf|jpg|jpeg|png)$/i;
const items = [];
const binaryData = $binary || {};
const emailMeta = {
  subject: $json.subject || '',
  from: ($json.from && $json.from.text) ? $json.from.text : String($json.from || ''),
  date: $json.date || new Date().toISOString()
};
for (const [key, att] of Object.entries(binaryData)) {
  if (!key.startsWith('attachment')) continue;
  const rawName = att.fileName || att.filename || (key + '.bin');
  if (!validExt.test(rawName)) continue;
  // Sanitiza el nombre para evitar path traversal
  const safeName = rawName.replace(/[^a-zA-Z0-9._\-]/g, '_').replace(/^\.+/, '');
  const savePath = '/data/pdf_excell/entrada_n8n_directo/' + safeName;
  items.push({
    json: { fileName: safeName, savePath, ...emailMeta },
    binary: { data: att }
  });
}
if (items.length === 0) return [];
return items;
